import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.CRfKVJQk.js";const g=JSON.parse('{"title":"03 · Android renderer","description":"Android is the reason this library exists, so this is the deepest doc.","frontmatter":{"description":"Android is the reason this library exists, so this is the deepest doc.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/architecture/03-android-renderer"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/architecture/03-android-renderer"}],["meta",{"property":"og:title","content":"03 · Android renderer · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"Android is the reason this library exists, so this is the deepest doc."}],["meta",{"name":"twitter:title","content":"03 · Android renderer · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"Android is the reason this library exists, so this is the deepest doc."}]]},"headers":[],"relativePath":"architecture/03-android-renderer.md","filePath":"architecture/03-android-renderer.md"}'),s={name:"architecture/03-android-renderer.md"};function o(n,e,i,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[d(`<h1 id="_03-·-android-renderer" tabindex="-1">03 · Android renderer <a class="header-anchor" href="#_03-·-android-renderer" aria-label="Permalink to &quot;03 · Android renderer&quot;">​</a></h1><p>Android is the reason this library exists, so this is the deepest doc.</p><hr><h2 id="_1-the-three-problems" tabindex="-1">1. The three problems <a class="header-anchor" href="#_1-the-three-problems" aria-label="Permalink to &quot;1. The three problems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Solution in this repo</th></tr></thead><tbody><tr><td>A view can&#39;t see the pixels behind it</td><td><strong>Dynamic background capture</strong>: <code>GlassBackdrop</code> records its drawing into a <code>RenderNode</code>, and glass re-draws that node</td></tr><tr><td>Old Androids have no GPU blur or shaders</td><td><strong>Tiers</strong>: SHADER (13+), BLUR (12), COMPAT (7–11)</td></tr><tr><td>Low-end phones can&#39;t afford full glass</td><td><strong>Quality levels</strong> + <code>auto</code> resolution</td></tr></tbody></table><hr><h2 id="_2-dynamic-background-capture" tabindex="-1">2. Dynamic background capture <a class="header-anchor" href="#_2-dynamic-background-capture" aria-label="Permalink to &quot;2. Dynamic background capture&quot;">​</a></h2><h3 id="what-a-rendernode-is-plain-language" tabindex="-1">What a RenderNode is (plain language) <a class="header-anchor" href="#what-a-rendernode-is-plain-language" aria-label="Permalink to &quot;What a RenderNode is (plain language)&quot;">​</a></h3><p>A <code>RenderNode</code> is a <strong>recording of drawing commands</strong> (&quot;draw this image here, draw this text there&quot;), not a picture. Recording is cheap, and the same recording can be played back in several places. If a child view changes (a list scrolls), the recording refers to the child&#39;s own node, so every playback shows the new content automatically.</p><h3 id="how-the-backdrop-records" tabindex="-1">How the backdrop records <a class="header-anchor" href="#how-the-backdrop-records" aria-label="Permalink to &quot;How the backdrop records&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GlassBackdropView.draw(canvas)</span></span>
<span class="line"><span>  if (Android 12+ &amp;&amp; a glass is bound &amp;&amp; hardware canvas)</span></span>
<span class="line"><span>      rc = contentNode.beginRecording()</span></span>
<span class="line"><span>      super.draw(rc)                 ← children draw into the recording</span></span>
<span class="line"><span>      contentNode.endRecording()</span></span>
<span class="line"><span>      canvas.drawRenderNode(contentNode)   ← screen shows it as normal</span></span>
<span class="line"><span>  else</span></span>
<span class="line"><span>      super.draw(canvas)             ← normal drawing, zero overhead</span></span></code></pre></div><p>Recording is <strong>off</strong> until some glass binds to the backdrop (<code>BackdropRegistry.updateRecordingFlags</code>).</p><h3 id="how-glass-plays-it-back" tabindex="-1">How glass plays it back <a class="header-anchor" href="#how-glass-plays-it-back" aria-label="Permalink to &quot;How glass plays it back&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glassNode (covers sampleRect = glass + pad, CLIPPED to the backdrop&#39;s bounds)</span></span>
<span class="line"><span>  record:</span></span>
<span class="line"><span>    translate(-sampleRect.left, -sampleRect.top)</span></span>
<span class="line"><span>    scale(1/squish) around centre      ← keep the world still while glass squishes</span></span>
<span class="line"><span>    concat(backdropToGlass matrix)     ← line the backdrop up with the screen</span></span>
<span class="line"><span>    drawRenderNode(backdrop.contentNode)</span></span>
<span class="line"><span>  effect:</span></span>
<span class="line"><span>    blur(blurPx) → saturation(1.35) → AGSL shader (13+)</span></span>
<span class="line"><span>canvas:</span></span>
<span class="line"><span>  clipPath(rounded shape) → translate(sampleRect.left, top) → drawRenderNode(glassNode)</span></span></code></pre></div><p>The <strong>padding</strong> (<code>GlassFrame.padPx</code> ≈ 2×blur + refraction reach, max 256 px) makes blur and refraction near the edges read real neighbouring content.</p><p>The sample area is <strong>clipped to the backdrop</strong> (<code>LiquidGlassView.computeSampleRect</code>). Without that, glass flush with the screen edge (tab bars, full-width headers) would blur empty pixels in and fade to see-through at that edge. With it, the CLAMP blur repeats the backdrop&#39;s edge pixels. The shader receives the node&#39;s position as <code>uOrigin</code>.</p><p>The <strong>matrix</strong> comes from <code>View.transformMatrixToGlobal</code> for both views (API 29+). That makes translate, scale, rotation, scroll offsets and Reanimated/native-driver transforms line up exactly. API 24–28 use window positions, so translation is exact and rotation/scale are ignored.</p><h3 id="how-glass-knows-when-to-redraw" tabindex="-1">How glass knows when to redraw <a class="header-anchor" href="#how-glass-knows-when-to-redraw" aria-label="Permalink to &quot;How glass knows when to redraw&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Signal</th><th>Source</th><th>Catches</th></tr></thead><tbody><tr><td>Content version</td><td><code>GlassBackdropView.onDescendantInvalidated</code> / <code>invalidateChildInParent</code> / <code>invalidate</code> → <code>BackdropRegistry.notifyContentChanged</code></td><td>Scrolling, images loading, animations <strong>inside</strong> the backdrop</td></tr><tr><td>Geometry</td><td><code>LiquidGlassView.onPreDraw</code> compares the backdrop→glass matrix with last frame</td><td>Glass or backdrop <strong>moving</strong> (including native-driver animations that never call <code>invalidate</code>)</td></tr><tr><td>Own state</td><td>prop commit, transition frames, touch/press/tilt</td><td>Everything the glass does itself</td></tr></tbody></table><p>All of these call <code>invalidate()</code> <strong>before</strong> drawing, so the glass updates in the <strong>same frame</strong>. There is no one-frame lag.</p><p><strong>Proximity filter.</strong> <code>onDescendantInvalidated(child, target)</code> tells the backdrop <em>which</em> view changed. <code>BackdropRegistry.notifyContentChanged</code> maps that view&#39;s rect to screen coordinates, unions it with where that view was last time (so a moving view leaves no ghost), and only invalidates glass views whose screen sample area overlaps it. A spinner in one corner no longer re-blurs every glass on screen. The backdrop&#39;s own <code>invalidate()</code> (and API 24–25) still notify every glass. On Android 12+ this also lets the GPU keep each glass&#39;s cached blur layer, because an un-invalidated glass doesn&#39;t re-record its node.</p><h3 id="matching-glass-to-a-backdrop" tabindex="-1">Matching glass to a backdrop <a class="header-anchor" href="#matching-glass-to-a-backdrop" aria-label="Permalink to &quot;Matching glass to a backdrop&quot;">​</a></h3><p><code>BackdropRegistry.resolve</code> (first match wins):</p><ol><li>same window only (a <code>Modal</code> is a separate window)</li><li>never a backdrop that contains the glass</li><li><code>backdropId</code> match, if given</li><li>otherwise the backdrop with the largest on-screen overlap; ties go to the newest</li></ol><hr><h2 id="_3-renderer-tiers" tabindex="-1">3. Renderer tiers <a class="header-anchor" href="#_3-renderer-tiers" aria-label="Permalink to &quot;3. Renderer tiers&quot;">​</a></h2><p><code>RendererFactory.choose</code> is the single decision point:</p><table tabindex="0"><thead><tr><th>Condition (first match wins)</th><th>Renderer</th></tr></thead><tbody><tr><td><code>reduceTransparency</code></td><td>SOLID (opaque <code>fallbackColor</code>)</td></tr><tr><td>no backdrop found</td><td>SOLID (frosted, 92% <code>fallbackColor</code>)</td></tr><tr><td><code>quality=&quot;static&quot;</code></td><td>COMPAT_STATIC</td></tr><tr><td>window not hardware accelerated</td><td>COMPAT_LIVE</td></tr><tr><td>API 33+, shader compiled, level HIGH/MEDIUM</td><td>SHADER</td></tr><tr><td>API 31+</td><td>BLUR</td></tr><tr><td>otherwise</td><td>COMPAT_LIVE</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Renderer</th><th>Blur</th><th>Refraction</th><th>Lighting</th><th>Cost</th></tr></thead><tbody><tr><td>SHADER</td><td>GPU <code>RenderEffect</code></td><td>AGSL</td><td>AGSL (rim, back-light, touch, press)</td><td>GPU only</td></tr><tr><td>BLUR</td><td>GPU <code>RenderEffect</code></td><td>—</td><td><code>SurfacePainter</code> (sheen, touch glow, press veil)</td><td>GPU only</td></tr><tr><td>COMPAT_LIVE</td><td>CPU StackBlur on a 1/4–1/8 bitmap</td><td>—</td><td><code>SurfacePainter</code></td><td>CPU, throttled</td></tr><tr><td>COMPAT_STATIC</td><td>same, captured once</td><td>—</td><td><code>SurfacePainter</code></td><td>once</td></tr><tr><td>SOLID</td><td>—</td><td>—</td><td>border only</td><td>~0</td></tr></tbody></table><p>All tiers finish with <code>SurfacePainter</code> (tint + border), so they look like one family.</p><h3 id="software-canvas-screenshots" tabindex="-1">Software canvas (screenshots) <a class="header-anchor" href="#software-canvas-screenshots" aria-label="Permalink to &quot;Software canvas (screenshots)&quot;">​</a></h3><p>If <code>onDraw</code> gets a non-hardware canvas (e.g. <code>react-native-view-shot</code> drawing into a Bitmap), RenderNodes can&#39;t be drawn. The GPU renderer then delegates that one draw to a private <code>CompatGlassRenderer</code>, so screenshots still contain believable glass instead of crashing.</p><hr><h2 id="_4-quality" tabindex="-1">4. Quality <a class="header-anchor" href="#_4-quality" aria-label="Permalink to &quot;4. Quality&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>SHADER tier</th><th>COMPAT tier</th></tr></thead><tbody><tr><td>HIGH</td><td>refraction + RGB split</td><td>capture every frame, 1/4 res</td></tr><tr><td>MEDIUM</td><td>refraction, no RGB split</td><td>capture ≤ every 32 ms, 1/4 res</td></tr><tr><td>LOW</td><td>BLUR renderer (no shader)</td><td>capture ≤ every 100 ms, 1/8 res</td></tr><tr><td>STATIC</td><td>COMPAT_STATIC</td><td>capture once + on move/resize</td></tr></tbody></table><p><code>QualityResolver</code> for <code>auto</code>:</p><ol><li>Start: HIGH on high-end Android 13+ (media performance class ≥ 12 <strong>or</strong> ≥ 6 GB RAM), otherwise MEDIUM.</li><li>Low-RAM device <strong>or</strong> battery saver → LOW.</li><li>More than 6 glass views in the window → one level down. More than 12 → LOW.</li></ol><p>It re-runs when battery saver toggles (<code>SystemSettingsMonitor</code>), when glass views are added or removed, and when <code>quality</code> changes.</p><p>Compat throttling applies to <strong>content</strong> changes only, and always has a <strong>trailing edge</strong>: if a change is throttled, the renderer sets <code>frame.redrawAfterMs</code>, and the view posts a delayed redraw. The final state after scrolling stops is always captured.</p><p><strong>Movement is never throttled on compat.</strong> When the glass or backdrop only translates, <code>BackdropSnapshot.draw</code> shifts the existing bitmap by the exact delta every frame (free). It re-captures immediately only when the shift would exceed half the padding, the snapshot no longer covers the glass, or scale/rotation changed. Glass cards scrolling over a wallpaper therefore stay aligned on Android 7–11. The press squish is compensated at draw time, so it&#39;s exact on every spring frame.</p><hr><h2 id="_5-the-shader-agsl" tabindex="-1">5. The shader (AGSL) <a class="header-anchor" href="#_5-the-shader-agsl" aria-label="Permalink to &quot;5. The shader (AGSL)&quot;">​</a></h2><p>Source: <code>shader/GlassShaderSource.kt</code>. It runs per pixel <strong>after</strong> blur and saturation.</p><table tabindex="0"><thead><tr><th>Step</th><th>What it does</th></tr></thead><tbody><tr><td>1 Shape</td><td>Signed distance to the rounded rect; pixels outside pass through</td></tr><tr><td>2 Rim</td><td><code>bend</code> = 1 at the edge → 0 at <code>edgeWidth</code> inside (smoothstep)</td></tr><tr><td>3 Normal</td><td>Direction the edge faces, from the distance field&#39;s gradient</td></tr><tr><td>4 Lens</td><td>Whole surface magnifies by up to 12% × <code>distortion</code> (+2.5% when pressed)</td></tr><tr><td>5 Refract</td><td>Near the rim, sample further inside along the normal × <code>refraction</code> × <code>edgeWidth</code></td></tr><tr><td>6 RGB split</td><td>Red and blue sampled at opposite offsets at the rim (<code>chromaticAberration</code>, HIGH only)</td></tr><tr><td>7 Light</td><td>Specular on the rim facing <code>lightDir</code>; faint back-light on the opposite rim; Gaussian glow under the finger; slight lift while pressed</td></tr></tbody></table><p>Uniforms are pushed only when a value changed (<code>GlassShader.effectFor</code> compares a 15-float array). A <code>RenderEffect</code> captures uniforms at creation, so a new effect is made only when something changed.</p><p><strong>Compile failure</strong> (rare GPU driver bugs): <code>GlassShader.createOrNull</code> catches it, sets <code>RendererTier.shaderBroken = true</code> for the process, and every glass view uses BLUR from then on.</p><hr><h2 id="_6-animation" tabindex="-1">6. Animation <a class="header-anchor" href="#_6-animation" aria-label="Permalink to &quot;6. Animation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Class</th><th>Behaviour</th><th>Reduce motion</th></tr></thead><tbody><tr><td>Prop transitions</td><td><code>GlassConfigTransition</code></td><td>180 ms ease between old and new config; interruptions continue from mid-state; angles take the short way round; colours use ARGB interpolation</td><td>snap</td></tr><tr><td>Touch light</td><td><code>TouchLightController</code></td><td>Fade in 120 ms at the finger, smoothed follow, fade out 320 ms. Observes touches only, never consumes them</td><td>instant on/off</td></tr><tr><td>Press squish</td><td><code>PressAnimator</code></td><td>0→1 in 110 ms; release springs back with overshoot (420 ms) for a jelly settle. Up to 3.5% smaller via <strong>canvas</strong> scale; the backdrop sample is counter-scaled so the world stays still</td><td>highlight only, no movement</td></tr><tr><td>Tilt lighting</td><td><code>MotionLightSource</code></td><td>One shared <code>GAME_ROTATION_VECTOR</code> listener (accelerometer fallback), smoothed, ±35°, paused in background via the TurboModule&#39;s lifecycle listener</td><td>off</td></tr></tbody></table><hr><h2 id="_7-fallbacks-at-a-glance-android" tabindex="-1">7. Fallbacks at a glance (Android) <a class="header-anchor" href="#_7-fallbacks-at-a-glance-android" aria-label="Permalink to &quot;7. Fallbacks at a glance (Android)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td>API 24–30</td><td>COMPAT snapshot renderer</td></tr><tr><td>Shader fails to compile</td><td>BLUR tier for the whole app</td></tr><tr><td>No hardware acceleration</td><td>COMPAT_LIVE</td></tr><tr><td>Software canvas (screenshot)</td><td>one-off compat draw</td></tr><tr><td>No backdrop / wrong <code>backdropId</code> / glass nested in its backdrop</td><td>SOLID frosted + one logcat warning</td></tr><tr><td>Snapshot capture throws (HARDWARE bitmaps)</td><td>SOLID, retried every 3 s, one warning</td></tr><tr><td>Out of memory creating a snapshot</td><td>SOLID, one warning</td></tr><tr><td><code>reduceTransparency</code></td><td>SOLID opaque, backdrop recording stops</td></tr></tbody></table><hr><h2 id="_8-performance-notes" tabindex="-1">8. Performance notes <a class="header-anchor" href="#_8-performance-notes" aria-label="Permalink to &quot;8. Performance notes&quot;">​</a></h2><ul><li>API 31+: <strong>no pixel readback</strong> ever. Blur and shader run on the RenderThread / GPU.</li><li>Backdrop recording costs roughly one extra display-list pass (CPU-side commands), and only while glass is bound.</li><li>Per-frame allocations are avoided: Shaders and RenderEffects are cached by key, and bitmaps and blur buffers are reused.</li><li>Built-in counters (<code>getGlassStats()</code> in JS; the example&#39;s Stress screen shows them per second): draws, GPU blur passes, shader passes, compat captures + ms, skipped far changes, solid draws, live views.</li><li>Glass count is the main cost driver on the GPU (each glass = one blur pass over its own area + padding). That&#39;s why <code>auto</code> steps down above 6 and 12 views.</li></ul>`,55)])])}const u=t(s,[["render",o]]);export{g as __pageData,u as default};
